function clockFor(renderer){let clock=clocks.get(renderer);if(!clock){clock=renderer.hbBackend==='webgpu'?new WebGPUClock(renderer):new GLClock(renderer);clocks.set(renderer,clock);const dispose=renderer.dispose;renderer.dispose=function(...args){clock.dispose();return dispose.apply(this,args);};}return clock;}
