export function withGPUFrameTiming(renderer,recording,draw){if(renderer.hbBackend==='d3d11')return draw();if(!recording){stopGPUFrameTiming(renderer);return draw();}let clock,active=false;try{clock=clockFor(renderer);if(!clock.dead)active=clock.begin();}catch(error){if(clock)failed(clock,error);}let success=false;try{const result=draw();success=true;return result;}finally{if(active)try{clock.end(success);}catch(error){failed(clock,error);}}}
